#!/usr/bin/env python3
"""
Unified Product Category Taxonomy Builder
Merges Amazon, Facebook, and Google Shopping category taxonomies into
a single 5-level unified taxonomy.
"""

import csv
import re
import os
from collections import defaultdict, Counter

# ============================================================
# PART 1: Data Loading & Normalization
# ============================================================

def load_categories(filepath, source_name):
    """Load category paths from a CSV file."""
    records = []
    with open(filepath, 'r', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            path = row['category_path'].strip().strip('"')
            parts = [p.strip() for p in path.split('>') if p.strip()]
            records.append({
                'source': source_name,
                'category_path': path,
                'levels': parts,
                'depth': len(parts)
            })
    return records


def normalize_text(text):
    """Normalize text for comparison."""
    t = text.lower().strip()
    t = re.sub(r'[,&]+', ' and ', t)
    t = re.sub(r'[^a-z0-9\s]', ' ', t)
    t = re.sub(r'\s+', ' ', t).strip()
    return t


def get_words(text):
    """Get significant words from text."""
    stop = {'and', 'or', 'the', 'a', 'an', 'for', 'of', 'in', 'to', 'with', 'by', 'from', 'on', 'at', 'other'}
    return set(w for w in normalize_text(text).split() if w not in stop and len(w) > 1)


def title_case(text):
    """Proper title case for category names."""
    words = text.strip().split()
    small = {'and', 'or', 'the', 'a', 'an', 'for', 'of', 'in', 'to', 'with', 'by', 'from', 'on', 'at', '&'}
    result = []
    for i, w in enumerate(words):
        if i == 0 or w.lower() not in small:
            result.append(w.capitalize())
        else:
            result.append(w.lower())
    return ' '.join(result)


def standardize_category_name(name):
    """Standardize a category name: title case, clean up."""
    name = name.strip()
    # Remove trailing/leading special chars
    name = re.sub(r'^[^a-zA-Z0-9]+|[^a-zA-Z0-9]+$', '', name)
    # Collapse whitespace
    name = re.sub(r'\s+', ' ', name)
    # Title case
    name = title_case(name)
    return name


def word_overlap(name1, name2):
    """Calculate word overlap ratio between two names."""
    w1 = get_words(name1)
    w2 = get_words(name2)
    if not w1 or not w2:
        return 0.0
    intersection = w1 & w2
    return len(intersection) / min(len(w1), len(w2))


# ============================================================
# PART 2: Level 1 Unified Category Mapping
# ============================================================

# Define the unified Level 1 taxonomy with mappings from each platform
LEVEL1_MAPPING = {
    "Electronics | Computers": {
        "amazon": ["Electronics", "Cell Phones & Accessories"],
        "facebook": ["electronics"],
        "google": ["Electronics", "Cameras & Optics"]
    },
    "Clothing | Shoes | Accessories": {
        "amazon": ["Clothing, Shoes & Jewelry"],
        "facebook": ["clothing & accessories", "jewelry & watches"],
        "google": ["Apparel & Accessories"]
    },
    "Home | Kitchen | Garden": {
        "amazon": ["Home & Kitchen", "Patio, Lawn & Garden"],
        "facebook": ["home", "patio & garden"],
        "google": ["Home & Garden", "Furniture"]
    },
    "Health | Beauty | Personal Care": {
        "amazon": ["Beauty & Personal Care", "Health & Household"],
        "facebook": ["health & beauty"],
        "google": ["Health & Beauty"]
    },
    "Food | Beverages | Grocery": {
        "amazon": ["Grocery & Gourmet Food"],
        "facebook": ["food & beverages"],
        "google": ["Food, Beverages & Tobacco"]
    },
    "Sports | Outdoors | Fitness": {
        "amazon": ["Sports & Outdoors"],
        "facebook": ["sporting goods"],
        "google": ["Sporting Goods"]
    },
    "Toys | Games | Hobbies": {
        "amazon": ["Toys & Games", "Video Games"],
        "facebook": ["toys & games"],
        "google": ["Toys & Games", "Software"]
    },
    "Baby | Toddler Products": {
        "amazon": ["Baby Products"],
        "facebook": ["baby products"],
        "google": ["Baby & Toddler"]
    },
    "Automotive | Vehicles | Parts": {
        "amazon": ["Automotive"],
        "facebook": ["auto parts & accessories"],
        "google": ["Vehicles & Parts"]
    },
    "Tools | Home Improvement": {
        "amazon": ["Tools & Home Improvement", "Appliances"],
        "facebook": ["home improvement"],
        "google": ["Hardware"]
    },
    "Books | Media | Entertainment": {
        "amazon": ["Books", "Movies & TV", "CDs & Vinyl"],
        "facebook": ["media"],
        "google": ["Media", "Arts & Entertainment"]
    },
    "Office | School Supplies": {
        "amazon": ["Office Products"],
        "facebook": ["office supplies"],
        "google": ["Office Supplies"]
    },
    "Pet Supplies | Animals": {
        "amazon": ["Pet Supplies"],
        "facebook": ["pet supplies"],
        "google": ["Animals & Pet Supplies"]
    },
    "Arts | Crafts | Sewing": {
        "amazon": ["Arts, Crafts & Sewing"],
        "facebook": ["arts & crafts"],
        "google": []
    },
    "Industrial | Scientific | Business": {
        "amazon": ["Industrial & Scientific"],
        "facebook": [],
        "google": ["Business & Industrial"]
    },
    "Musical Instruments | Audio": {
        "amazon": ["Musical Instruments"],
        "facebook": ["musical instruments"],
        "google": []
    },
    "Luggage | Travel | Bags": {
        "amazon": [],
        "facebook": ["travel & luggage"],
        "google": ["Luggage & Bags"]
    },
    "Collectibles | Specialty Items": {
        "amazon": [],
        "facebook": ["antiques & collectibles", "other"],
        "google": ["Mature", "Religious & Ceremonial"]
    }
}


def build_source_to_level1():
    """Build a reverse mapping: (source, original_top) -> unified_level_1."""
    mapping = {}
    for unified, sources in LEVEL1_MAPPING.items():
        for source, tops in sources.items():
            for top in tops:
                mapping[(source, top.lower())] = unified
    return mapping


# ============================================================
# PART 3: Deeper Level Mapping (Levels 2-5)
# ============================================================

def assign_unified_levels(record, source_to_l1):
    """Assign unified levels 1-5 for a single record."""
    source = record['source']
    levels = record['levels']
    depth = record['depth']

    # Level 1: map from top-level
    top = levels[0] if levels else ''
    key = (source, top.lower())
    unified_l1 = source_to_l1.get(key, '')

    if not unified_l1:
        # Fallback: try keyword matching
        unified_l1 = fallback_level1(top)

    # For deeper levels, we standardize the original category names
    # and map them into our 5-level structure
    unified = [''] * 5
    unified[0] = unified_l1

    # Map original levels to unified levels 2-5
    # Strategy: use original hierarchy, standardizing names
    # Original level 1 -> unified level 1 (already done)
    # Original level 2 -> unified level 2
    # Original level 3 -> unified level 3
    # Original level 4 -> unified level 4
    # Original levels 5+ -> unified level 5 (concatenated if needed)

    for i in range(1, min(5, depth)):
        name = standardize_category_name(levels[i])
        # Truncate to max 5 words
        words = name.split()
        if len(words) > 5:
            name = ' '.join(words[:5])
        unified[i] = name

    # If depth > 5, merge levels 5+ into level 5
    if depth > 5:
        extra = [standardize_category_name(levels[j]) for j in range(4, depth)]
        merged = ' | '.join(extra)
        # Truncate to 5 words
        words = merged.split()
        if len(words) > 5:
            merged = ' '.join(words[:5])
        unified[4] = merged

    record['unified_level_1'] = unified[0]
    record['unified_level_2'] = unified[1]
    record['unified_level_3'] = unified[2]
    record['unified_level_4'] = unified[3]
    record['unified_level_5'] = unified[4]
    return record


def fallback_level1(top_name):
    """Fallback level 1 assignment based on keywords."""
    tn = top_name.lower()
    if any(w in tn for w in ['electron', 'phone', 'camera', 'computer']):
        return "Electronics | Computers"
    if any(w in tn for w in ['cloth', 'shoe', 'jewel', 'apparel', 'fashion', 'accessori']):
        return "Clothing | Shoes | Accessories"
    if any(w in tn for w in ['home', 'kitchen', 'garden', 'furniture', 'patio']):
        return "Home | Kitchen | Garden"
    if any(w in tn for w in ['health', 'beauty', 'personal']):
        return "Health | Beauty | Personal Care"
    if any(w in tn for w in ['food', 'beverage', 'grocery', 'gourmet']):
        return "Food | Beverages | Grocery"
    if any(w in tn for w in ['sport', 'outdoor', 'fitness', 'athletic']):
        return "Sports | Outdoors | Fitness"
    if any(w in tn for w in ['toy', 'game', 'video game', 'hobby']):
        return "Toys | Games | Hobbies"
    if any(w in tn for w in ['baby', 'toddler', 'infant']):
        return "Baby | Toddler Products"
    if any(w in tn for w in ['auto', 'vehicle', 'car']):
        return "Automotive | Vehicles | Parts"
    if any(w in tn for w in ['tool', 'hardware', 'improvement', 'appliance']):
        return "Tools | Home Improvement"
    if any(w in tn for w in ['book', 'media', 'movie', 'music', 'entertainment', 'cd', 'vinyl', 'art']):
        return "Books | Media | Entertainment"
    if any(w in tn for w in ['office', 'school']):
        return "Office | School Supplies"
    if any(w in tn for w in ['pet', 'animal']):
        return "Pet Supplies | Animals"
    if any(w in tn for w in ['craft', 'sewing']):
        return "Arts | Crafts | Sewing"
    if any(w in tn for w in ['industrial', 'scientific', 'business']):
        return "Industrial | Scientific | Business"
    if any(w in tn for w in ['musical', 'instrument']):
        return "Musical Instruments | Audio"
    if any(w in tn for w in ['luggage', 'travel', 'bag']):
        return "Luggage | Travel | Bags"
    if any(w in tn for w in ['collecti', 'antique', 'mature', 'religious', 'ceremon']):
        return "Collectibles | Specialty Items"
    if any(w in tn for w in ['software']):
        return "Toys | Games | Hobbies"
    return "Collectibles | Specialty Items"  # catch-all


# ============================================================
# PART 4: Post-Processing & Standardization
# ============================================================

def standardize_level2_names(records):
    """Standardize level 2 names across sources to unify similar categories."""
    # Build mapping of similar L2 names within each L1
    l1_l2_groups = defaultdict(lambda: defaultdict(list))
    for rec in records:
        l1 = rec['unified_level_1']
        l2 = rec['unified_level_2']
        if l2:
            l1_l2_groups[l1][normalize_text(l2)].append(l2)

    # For each L1, create standardized L2 names
    l2_standardization = {}
    for l1, l2_map in l1_l2_groups.items():
        for norm_key, variants in l2_map.items():
            # Use the most common variant
            most_common = Counter(variants).most_common(1)[0][0]
            for v in variants:
                l2_standardization[(l1, v)] = most_common

    # Apply standardization
    for rec in records:
        l1 = rec['unified_level_1']
        l2 = rec['unified_level_2']
        if l2 and (l1, l2) in l2_standardization:
            rec['unified_level_2'] = l2_standardization[(l1, l2)]

    return records


def merge_similar_level2(records):
    """Merge L2 categories that are very similar within same L1."""
    # Collect all unique L1->L2 combinations
    l1_l2s = defaultdict(set)
    for rec in records:
        if rec['unified_level_2']:
            l1_l2s[rec['unified_level_1']].add(rec['unified_level_2'])

    # Build merge map for very similar L2s
    merge_map = {}
    for l1, l2s in l1_l2s.items():
        l2_list = sorted(l2s)
        for i, a in enumerate(l2_list):
            for b in l2_list[i+1:]:
                ov = word_overlap(a, b)
                if ov >= 0.6:  # High overlap - merge
                    # Keep the shorter/simpler name
                    keep = a if len(a) <= len(b) else b
                    discard = b if keep == a else a
                    merge_map[(l1, discard)] = keep

    # Apply merge
    for rec in records:
        key = (rec['unified_level_1'], rec['unified_level_2'])
        if key in merge_map:
            rec['unified_level_2'] = merge_map[key]

    return records


def fix_parent_child_overlap(records):
    """Fix cases where child name overlaps too much with parent."""
    for rec in records:
        for i in range(1, 5):
            parent_key = f'unified_level_{i}'
            child_key = f'unified_level_{i+1}'
            parent = rec[parent_key]
            child = rec[child_key]
            if parent and child:
                ov = word_overlap(parent, child)
                if ov > 0.5:
                    # Remove overlapping words from child
                    parent_words = get_words(parent)
                    child_words_list = child.split()
                    new_child_words = [w for w in child_words_list
                                       if w.lower() not in parent_words]
                    if new_child_words:
                        rec[child_key] = ' '.join(new_child_words)
                    # If all words removed, keep original
    return records


def ensure_depth_assignment(records):
    """Ensure depth matches the number of non-empty unified levels."""
    for rec in records:
        actual_depth = 0
        for i in range(1, 6):
            if rec.get(f'unified_level_{i}', ''):
                actual_depth = i
        rec['depth'] = actual_depth
    return records


# ============================================================
# PART 5: L2 Consolidation - Ensure 3-20 subcategories per parent
# ============================================================

def consolidate_subcategories(records, max_children=20, min_children=3):
    """
    Ensure each parent has between min_children and max_children subcategories.
    If too many, group them. If too few, merge into 'General' or parent name.
    """
    for level in range(1, 5):
        parent_col = f'unified_level_{level}'
        child_col = f'unified_level_{level+1}'

        # Count children per parent
        parent_children = defaultdict(lambda: defaultdict(int))
        for rec in records:
            parent = rec.get(parent_col, '')
            child = rec.get(child_col, '')
            if parent and child:
                parent_children[parent][child] += 1

        # Handle parents with too many children
        for parent, children in parent_children.items():
            child_list = sorted(children.keys())
            if len(child_list) > max_children:
                # Group smaller categories into "Other" bucket
                # Sort by frequency, keep top max_children-1, group rest
                sorted_children = sorted(children.items(), key=lambda x: -x[1])
                keep = {c for c, _ in sorted_children[:max_children-1]}
                other_label = f"Other {parent.split('|')[0].strip()}" if '|' in parent else f"Other {parent.split()[0]}"
                words = other_label.split()
                if len(words) > 5:
                    other_label = ' '.join(words[:5])

                for rec in records:
                    if rec.get(parent_col) == parent and rec.get(child_col, '') and rec[child_col] not in keep:
                        # Shift current child down
                        old_child = rec[child_col]
                        rec[child_col] = other_label
                        # Push old child to next level if possible
                        next_col = f'unified_level_{level+2}' if level + 2 <= 5 else None
                        if next_col and not rec.get(next_col, ''):
                            rec[next_col] = old_child

    return records


# ============================================================
# PART 6: Output Generation
# ============================================================

def write_full_csv(records, filepath):
    """Write the unified_taxonomy_full.csv."""
    with open(filepath, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['source', 'category_path', 'depth',
                         'unified_level_1', 'unified_level_2',
                         'unified_level_3', 'unified_level_4',
                         'unified_level_5'])
        for rec in records:
            writer.writerow([
                rec['source'],
                rec['category_path'],
                rec['depth'],
                rec.get('unified_level_1', ''),
                rec.get('unified_level_2', ''),
                rec.get('unified_level_3', ''),
                rec.get('unified_level_4', ''),
                rec.get('unified_level_5', '')
            ])


def write_hierarchy_csv(records, filepath):
    """Write unified_taxonomy_hierarchy.csv with all unique paths."""
    paths = set()
    for rec in records:
        for d in range(1, 6):
            path_parts = []
            all_filled = True
            for i in range(1, d+1):
                val = rec.get(f'unified_level_{i}', '')
                if val:
                    path_parts.append(val)
                else:
                    all_filled = False
                    break
            if all_filled and path_parts:
                padded = tuple(path_parts) + ('',) * (5 - len(path_parts))
                paths.add(padded)

    sorted_paths = sorted(paths)
    with open(filepath, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['unified_level_1', 'unified_level_2',
                         'unified_level_3', 'unified_level_4',
                         'unified_level_5'])
        for path in sorted_paths:
            writer.writerow(path)


# ============================================================
# PART 7: Validation
# ============================================================

def validate_taxonomy(records):
    """Validate the taxonomy against all rules."""
    errors = []
    warnings = []

    # Rule 1: 10-20 top-level categories
    l1s = set(rec['unified_level_1'] for rec in records if rec['unified_level_1'])
    if len(l1s) < 10:
        errors.append(f"Only {len(l1s)} level-1 categories (need 10-20)")
    elif len(l1s) > 20:
        errors.append(f"{len(l1s)} level-1 categories (need 10-20)")
    else:
        print(f"  [OK] Level 1 has {len(l1s)} categories (10-20 required)")

    # Check children counts per parent at each level
    for level in range(1, 5):
        parent_col = f'unified_level_{level}'
        child_col = f'unified_level_{level+1}'
        parent_children = defaultdict(set)
        for rec in records:
            parent = rec.get(parent_col, '')
            child = rec.get(child_col, '')
            if parent and child:
                parent_children[parent].add(child)

        for parent, children in parent_children.items():
            if len(children) < 3:
                warnings.append(f"L{level}->L{level+1}: '{parent}' has only {len(children)} children (need 3+)")
            elif len(children) > 20:
                warnings.append(f"L{level}->L{level+1}: '{parent}' has {len(children)} children (need <=20)")

    # Rule 5: Sibling distinctness (<30% word overlap)
    for level in range(1, 5):
        parent_col = f'unified_level_{level}'
        child_col = f'unified_level_{level+1}'
        parent_children = defaultdict(set)
        for rec in records:
            parent = rec.get(parent_col, '')
            child = rec.get(child_col, '')
            if parent and child:
                parent_children[parent].add(child)

        high_overlap_count = 0
        for parent, children in parent_children.items():
            children_list = sorted(children)
            for i, a in enumerate(children_list):
                for b in children_list[i+1:]:
                    ov = word_overlap(a, b)
                    if ov >= 0.3:
                        high_overlap_count += 1

        if high_overlap_count > 0:
            warnings.append(f"L{level+1}: {high_overlap_count} sibling pairs with >=30% word overlap")

    # Rule 7: Source distribution
    l1_sources = defaultdict(lambda: defaultdict(int))
    for rec in records:
        l1 = rec['unified_level_1']
        src = rec['source']
        if l1:
            l1_sources[l1][src] += 1

    print("\n  Source distribution across Level 1:")
    for l1 in sorted(l1_sources.keys()):
        dist = l1_sources[l1]
        total = sum(dist.values())
        parts = ', '.join(f"{s}:{c}" for s, c in sorted(dist.items()))
        sources_present = len(dist)
        marker = "[OK]" if sources_present >= 2 else "[WARN]"
        print(f"    {marker} {l1}: {parts} (total: {total})")

    # Pyramid structure
    level_counts = defaultdict(int)
    for rec in records:
        for i in range(1, 6):
            if rec.get(f'unified_level_{i}', ''):
                level_counts[i] += 1

    print("\n  Pyramid structure (records per level):")
    for level in sorted(level_counts.keys()):
        print(f"    Level {level}: {level_counts[level]} records")

    # Unique nodes per level
    unique_per_level = {}
    for level in range(1, 6):
        col = f'unified_level_{level}'
        unique_per_level[level] = len(set(rec[col] for rec in records if rec.get(col, '')))

    print("\n  Unique categories per level:")
    for level in sorted(unique_per_level.keys()):
        print(f"    Level {level}: {unique_per_level[level]} unique categories")

    if errors:
        print(f"\n  ERRORS: {len(errors)}")
        for e in errors:
            print(f"    - {e}")
    if warnings:
        print(f"\n  WARNINGS: {len(warnings)} (showing first 20)")
        for w in warnings[:20]:
            print(f"    - {w}")

    return errors, warnings


# ============================================================
# MAIN
# ============================================================

def main():
    print("Loading data...")
    amazon = load_categories('/root/data/amazon_product_categories.csv', 'amazon')
    facebook = load_categories('/root/data/fb_product_categories.csv', 'facebook')
    google = load_categories('/root/data/google_shopping_product_categories.csv', 'google')

    all_records = amazon + facebook + google
    print(f"  Loaded {len(amazon)} Amazon, {len(facebook)} Facebook, {len(google)} Google records")
    print(f"  Total: {len(all_records)} records")

    # Build source->L1 mapping
    source_to_l1 = build_source_to_level1()

    # Assign unified levels
    print("\nAssigning unified levels...")
    for rec in all_records:
        assign_unified_levels(rec, source_to_l1)

    # Standardize L2 names
    print("Standardizing level 2 names...")
    all_records = standardize_level2_names(all_records)
    all_records = merge_similar_level2(all_records)

    # Fix parent-child overlap
    print("Fixing parent-child overlaps...")
    all_records = fix_parent_child_overlap(all_records)

    # Consolidate subcategories
    print("Consolidating subcategories...")
    all_records = consolidate_subcategories(all_records)

    # Ensure depth assignment
    all_records = ensure_depth_assignment(all_records)

    # Validate
    print("\nValidation:")
    errors, warnings = validate_taxonomy(all_records)

    # Write outputs
    os.makedirs('/root/output', exist_ok=True)
    print("\nWriting output files...")
    write_full_csv(all_records, '/root/output/unified_taxonomy_full.csv')
    write_hierarchy_csv(all_records, '/root/output/unified_taxonomy_hierarchy.csv')

    # Count outputs
    with open('/root/output/unified_taxonomy_full.csv', 'r') as f:
        full_count = sum(1 for _ in f) - 1
    with open('/root/output/unified_taxonomy_hierarchy.csv', 'r') as f:
        hier_count = sum(1 for _ in f) - 1

    print(f"\n  unified_taxonomy_full.csv: {full_count} rows")
    print(f"  unified_taxonomy_hierarchy.csv: {hier_count} rows")
    print("\nDone!")


if __name__ == '__main__':
    main()

