print("Remaining L2 sibling overlap pairs (>=30%):")
total = 0
for l1 in sorted(l1_l2.keys()):
    children = sorted(l1_l2[l1])
    for i, a in enumerate(children):
        for b in children[i+1:]:
            ov = word_overlap(a, b)
